INSERT INTO grammar_lessons (id, grammar_chapter_id, title, pattern, meaning_vi, explanation, formation, jlpt_level_id, display_order, is_published, version) VALUES
(295, 64, 'Bài 1.1 - ～際(に)', '～際(に)', 'Khi, nhân lúc, nhân dịp', 'Dùng để diễn đạt ý ''Khi, nhân lúc, nhân dịp''. Khi dùng trong câu, hãy chú ý thể đứng trước mẫu và sắc thái trang trọng/thân mật theo ngữ cảnh.', '～際(に)', 4, 1, TRUE, 1),
(296, 64, 'Bài 1.2 - ～に際して／～にあたって', '～に際して／～にあたって', 'Tại thời điểm, nhân dịp', 'Dùng để diễn đạt ý ''Tại thời điểm, nhân dịp''. Khi dùng trong câu, hãy chú ý thể đứng trước mẫu và sắc thái trang trọng/thân mật theo ngữ cảnh.', '～に際して／～にあたって', 4, 2, TRUE, 1),
(297, 64, 'Bài 1.3 - ～たとたん(に)', '～たとたん(に)', 'Ngay khi vừa mới thì', 'Dùng để diễn đạt ý ''Ngay khi vừa mới thì''. Khi dùng trong câu, hãy chú ý thể đứng trước mẫu và sắc thái trang trọng/thân mật theo ngữ cảnh.', '～たとたん(に)', 4, 3, TRUE, 1),
